"""Frozen pre-changes DDL used by historical upgrade steps before changes_migration."""

from __future__ import annotations

PRE_CHANGES_SHEETS_TABLE_SQL = "CREATE TABLE IF NOT EXISTS sheets (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  position INTEGER NOT NULL DEFAULT 0,\n  parent_sheet_id INTEGER REFERENCES sheets(id),\n  parent_op_id INTEGER,\n  hidden INTEGER NOT NULL DEFAULT 0,\n  -- Derived-sheet staleness watermark (lazy pull idiom, cf. fts_state.indexed_at_op).\n  -- last_verified_op_cursor is the op_cursor a derived sheet was last\n  -- materialized/refreshed against; NULL means \"never refreshed since creation\"\n  -- and the resolver falls back to parent_op_id. stale_reason/stale_at are an\n  -- observability cache computed lazily at read time -- the resolver NEVER trusts\n  -- them across cursor rewinds (undo/redo move op_cursor); it recomputes from the\n  -- watermark every read.\n  last_verified_op_cursor INTEGER,\n  stale_reason TEXT,\n  stale_at TEXT,\n  -- sheet.refresh claim/lease (mirrors embedding_indexes): a non-null token\n  -- past its lease is a crashed refresh and is reclaimable; two live refreshes\n  -- of one sheet conflict on sheet_refresh_busy.\n  refresh_claim_token TEXT,\n  refresh_lease_expires_at TEXT,\n  -- Sheet-level row-title override\n  -- item 22): the column '...' menu's \"Use as row title\" sets this to a\n  -- columns(id); NULL means \"no explicit override\" and every reader falls\n  -- back to the frontend's default (first column per the grid's current\n  -- drag order, falling back to canonical column order) via the shared\n  -- web/src/workbench/rowTitle.ts helper. Not FK-constrained: a stale id\n  -- (its column deleted/hidden-by-undo) is treated as unset by every reader,\n  -- same idiom as parent_op_id.\n  title_column_id INTEGER,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);"

PRE_CHANGES_CURRENT_CELLS_TABLE_SQL = "CREATE TABLE IF NOT EXISTS current_cells (\n  column_id INTEGER NOT NULL REFERENCES columns(id) ON DELETE CASCADE,\n  row_id INTEGER NOT NULL REFERENCES rows(id) ON DELETE CASCADE,\n  retrieval_revision INTEGER NOT NULL CHECK (retrieval_revision > 0),\n  origin_kind TEXT NOT NULL CHECK (\n    origin_kind IN ('source_cell', 'run_result', 'manual_edit', 'copied_result')\n  ),\n  origin_op_id INTEGER REFERENCES ops(id) ON DELETE CASCADE,\n  origin_run_id INTEGER REFERENCES runs(id) ON DELETE CASCADE,\n  base_producer_id INTEGER REFERENCES base_cell_producers(id) ON DELETE RESTRICT,\n  validity TEXT NOT NULL CHECK (validity IN ('valid', 'missing', 'invalid')),\n  inline_value_kind TEXT CHECK (inline_value_kind IN (\n    'null','text','integer','real','boolean','bigint'\n  )),\n  inline_value,\n  outcome TEXT NOT NULL DEFAULT 'completed' CHECK(outcome IN ('completed','pending','failed','not_completed')),\n  CHECK (\n    (inline_value_kind IS NULL AND inline_value IS NULL)\n    OR (inline_value_kind='null' AND inline_value IS NULL)\n    OR (inline_value_kind='text' AND typeof(inline_value)='text')\n    OR (inline_value_kind='integer' AND typeof(inline_value)='integer')\n    OR (inline_value_kind='real' AND typeof(inline_value)='real'\n        AND inline_value=inline_value\n        AND abs(inline_value)<=1.7976931348623157e308)\n    OR (inline_value_kind='boolean' AND typeof(inline_value)='integer'\n        AND inline_value IN (0,1))\n    OR (inline_value_kind='bigint' AND typeof(inline_value)='text')\n  ),\n  CHECK (\n    (\n      origin_kind='source_cell'\n      AND origin_op_id IS NULL\n      AND origin_run_id IS NULL\n    )\n    OR (\n      origin_kind='run_result'\n      AND origin_op_id IS NOT NULL\n      AND origin_run_id IS NOT NULL\n      AND base_producer_id IS NULL\n    )\n    OR (\n      origin_kind='copied_result'\n      AND origin_op_id IS NOT NULL\n      AND base_producer_id IS NULL\n    )\n    OR (\n      origin_kind='manual_edit'\n      AND origin_op_id IS NOT NULL\n      AND origin_run_id IS NULL\n      AND base_producer_id IS NULL\n    )\n  )\n);"

PRE_CHANGES_TRIGGERS_SQL = {
    "trg_cell_result_heads_require_publishable_result": "CREATE TRIGGER IF NOT EXISTS trg_cell_result_heads_require_publishable_result\nBEFORE INSERT ON cell_result_heads\nWHEN NOT EXISTS (\n  SELECT 1\n  FROM results result\n  JOIN run_output_generations generation\n    ON generation.run_id = result.run_id\n   AND generation.column_id = result.column_id\n  JOIN runs run ON run.id = generation.run_id\n  JOIN ops op ON op.id = run.op_id\n  WHERE result.run_id = NEW.run_id\n    AND result.row_id = NEW.row_id\n    AND result.column_id = NEW.column_id\n    AND result.publication_effect IN ('publish_value','publish_null','publish_error')\n    AND generation.state IN ('active', 'staged', 'sealed')\n    AND op.status = 'applied'\n)\nBEGIN\n  SELECT RAISE(ABORT, 'cell head requires an applied publishable result');\nEND;",
    "trg_cell_result_heads_update_publishable_result": "CREATE TRIGGER IF NOT EXISTS trg_cell_result_heads_update_publishable_result\nBEFORE UPDATE ON cell_result_heads\nWHEN NOT EXISTS (\n  SELECT 1\n  FROM results result\n  JOIN run_output_generations generation\n    ON generation.run_id = result.run_id\n   AND generation.column_id = result.column_id\n  JOIN runs run ON run.id = generation.run_id\n  JOIN ops op ON op.id = run.op_id\n  WHERE result.run_id = NEW.run_id\n    AND result.row_id = NEW.row_id\n    AND result.column_id = NEW.column_id\n    AND result.publication_effect IN ('publish_value','publish_null','publish_error')\n    AND generation.state IN ('active', 'staged', 'sealed')\n    AND op.status = 'applied'\n)\nBEGIN\n  SELECT RAISE(ABORT, 'cell head requires an applied publishable result');\nEND;",
}

PRE_CHANGES_CHANGE_SCHEMA_SQL = "\nCREATE UNIQUE INDEX IF NOT EXISTS idx_ops_change_order ON ops(change_order);\nCREATE INDEX IF NOT EXISTS idx_run_rows_row ON run_rows(row_id,run_id);\n\n-- One immutable reference per effective cell at the history cutover. Payloads\n-- remain in their original version tables; old operation state is irrelevant.\nCREATE TABLE IF NOT EXISTS cell_baseline (\n  row_id INTEGER NOT NULL REFERENCES rows(id) ON DELETE CASCADE,\n  column_id INTEGER NOT NULL REFERENCES columns(id) ON DELETE CASCADE,\n  origin_kind TEXT NOT NULL,\n  origin_op_id INTEGER REFERENCES ops(id),\n  origin_run_id INTEGER REFERENCES runs(id),\n  base_producer_id INTEGER REFERENCES base_cell_producers(id),\n  PRIMARY KEY(column_id,row_id,origin_kind)\n);\nCREATE TABLE IF NOT EXISTS cell_authority_revisions (\n  column_id INTEGER PRIMARY KEY REFERENCES columns(id) ON DELETE CASCADE,\n  revision INTEGER NOT NULL DEFAULT 1\n);\nCREATE TABLE IF NOT EXISTS current_cell_repair (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  column_id INTEGER NOT NULL REFERENCES columns(id) ON DELETE CASCADE,\n  row_id_start INTEGER NOT NULL,\n  row_id_end INTEGER NOT NULL,\n  cursor INTEGER NOT NULL DEFAULT 0,\n  CHECK(row_id_start<=row_id_end)\n);\nCREATE INDEX IF NOT EXISTS idx_cell_repair_column ON current_cell_repair(column_id,row_id_start,row_id_end);\n\nCREATE VIEW IF NOT EXISTS cell_contributions AS\nSELECT cell.row_id,cell.column_id,'source_cell' AS origin_kind,\n       NULL AS origin_op_id,NULL AS origin_run_id,cell.producer_id AS base_producer_id,\n       op.change_order,1 AS publication_closed,0 AS edit_supersession\nFROM cells cell JOIN base_cell_producers producer ON producer.id=cell.producer_id\nJOIN ops op ON op.id=producer.op_id\nWHERE op.status='applied' AND op.change_order IS NOT NULL\nUNION ALL\nSELECT scope.row_id,generation.column_id,'run_result',run.op_id,run.id,NULL,\n       op.change_order,op.publication_closed,\n       CASE WHEN generation.write_mode!='replace_scope' THEN 0\n            WHEN json_type(op.undo_info,'$.column_types_after.\"'||generation.column_id||'\"') IS NOT NULL OR json_type(op.undo_info,'$.column_formats_after.\"'||generation.column_id||'\"') IS NOT NULL OR json_type(op.undo_info,'$.column_semantic_types_after.\"'||generation.column_id||'\"') IS NOT NULL THEN 2 ELSE 1 END\nFROM run_output_generations generation JOIN runs run ON run.id=generation.run_id\nJOIN ops op ON op.id=run.op_id JOIN run_rows scope ON scope.run_id=run.id\nWHERE op.status='applied' AND op.change_order IS NOT NULL\nAND generation.state!='staged'\nAND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(json_extract(\n op.undo_info,'$.unpublished_generation_columns'),'[]')) unpublished\n WHERE CAST(unpublished.value AS INTEGER)=generation.column_id)\nAND NOT EXISTS (SELECT 1 FROM results retained WHERE retained.run_id=run.id\n AND retained.row_id=scope.row_id AND retained.column_id=generation.column_id\n AND retained.publication_effect='retain')\nUNION ALL\nSELECT edit.row_id,edit.column_id,'manual_edit',edit.op_id,NULL,NULL,\n       op.change_order,1,CASE WHEN op.kind='review.decision' AND json_extract(op.spec,'$.params.decision')='reject_clear' THEN 1 ELSE 2 END\nFROM edits edit JOIN ops op ON op.id=edit.op_id\nWHERE op.status='applied' AND op.change_order IS NOT NULL\nUNION ALL\nSELECT copy.row_id,copy.column_id,'copied_result',copy.op_id,copy.source_run_id,NULL,\n       op.change_order,1,CASE WHEN json_type(op.undo_info,'$.column_types_after.\"'||copy.column_id||'\"') IS NOT NULL OR json_type(op.undo_info,'$.column_formats_after.\"'||copy.column_id||'\"') IS NOT NULL OR json_type(op.undo_info,'$.column_semantic_types_after.\"'||copy.column_id||'\"') IS NOT NULL THEN 2 ELSE 1 END\nFROM copied_result_outcomes copy JOIN ops op ON op.id=copy.op_id\nWHERE op.status='applied' AND op.change_order IS NOT NULL\nUNION ALL\nSELECT baseline.row_id,baseline.column_id,baseline.origin_kind,baseline.origin_op_id,\n       baseline.origin_run_id,baseline.base_producer_id,0,1,\n       CASE WHEN baseline.origin_kind!='manual_edit' THEN 0\n            WHEN EXISTS (SELECT 1 FROM ops op WHERE op.id=baseline.origin_op_id AND op.kind='review.decision' AND json_extract(op.spec,'$.params.decision')='reject_clear') THEN 1 ELSE 2 END\nFROM cell_baseline baseline;\nCREATE VIEW IF NOT EXISTS canonical_cell_heads AS\n\nSELECT payload.column_id,payload.row_id,\n       COALESCE(revision.revision,1) AS retrieval_revision,\n       payload.origin_kind,payload.origin_op_id,payload.origin_run_id,payload.base_producer_id,\n       CASE\n         WHEN payload.value_kind IS NULL OR payload.value_kind='null' THEN 'missing'\n         WHEN descriptor.type IN ('text','category','timestamped_transcript')\n           AND payload.value_kind='text' THEN 'valid'\n         WHEN descriptor.type='json' AND payload.value_kind='json' THEN 'valid'\n         WHEN descriptor.type IN ('number','integer','boolean') AND payload.value_kind IN ('text','json')\n           THEN 'invalid'\n         ELSE frisket_cell_validity(descriptor.type,payload.value_kind,payload.value)\n       END AS validity,\n       CASE WHEN payload.value_kind IN ('null','integer','real','boolean')\n         OR (payload.value_kind IN ('text','bigint') AND length(CAST(payload.value AS BLOB))<=512)\n         THEN payload.value_kind END AS inline_value_kind,\n       CASE WHEN payload.value_kind IN ('null','integer','real','boolean')\n         OR (payload.value_kind IN ('text','bigint') AND length(CAST(payload.value AS BLOB))<=512)\n         THEN payload.value END AS inline_value,\n       payload.outcome\nFROM (\n  SELECT ranked.*,\n       CASE ranked.origin_kind\n         WHEN 'source_cell' THEN cell.value_kind\n         WHEN 'copied_result' THEN CASE WHEN copy.outcome='completed' THEN copy.value_kind END\n         WHEN 'manual_edit' THEN edit.value_kind\n         WHEN 'run_result' THEN CASE result.publication_effect\n           WHEN 'publish_value' THEN result.value_kind WHEN 'publish_null' THEN 'null' END END AS value_kind,\n       CASE ranked.origin_kind\n         WHEN 'source_cell' THEN cell.value WHEN 'manual_edit' THEN edit.value\n         WHEN 'copied_result' THEN CASE WHEN copy.outcome='completed' THEN copy.value END\n         WHEN 'run_result' THEN CASE WHEN result.publication_effect='publish_value' THEN result.value END END AS value,\n       CASE WHEN ranked.origin_kind='copied_result' THEN copy.outcome\n            WHEN ranked.origin_kind!='run_result' THEN 'completed'\n            WHEN result.publication_effect IN ('publish_value','publish_null') THEN 'completed'\n            WHEN result.outcome='not_completed' THEN 'not_completed'\n            WHEN result.row_id IS NOT NULL THEN 'failed'\n            WHEN ranked.publication_closed=0 THEN 'pending' ELSE 'not_completed' END AS outcome\n  FROM (\n    SELECT ordered.*,ROW_NUMBER() OVER (\n      PARTITION BY ordered.column_id,ordered.row_id\n      ORDER BY CASE WHEN ordered.origin_kind='manual_edit'\n            AND COALESCE(ordered.last_overwrite,-1)<ordered.change_order\n            AND COALESCE(ordered.last_descriptor_replacement,-1)<ordered.change_order\n            AND (ordered.edit_supersession=2\n              OR COALESCE(ordered.last_replacement,-1)<ordered.change_order)\n          THEN MAX(ordered.change_order,COALESCE(ordered.last_generated,-1))\n          ELSE ordered.change_order END DESC,\n        CASE ordered.origin_kind WHEN 'manual_edit' THEN 2 WHEN 'run_result' THEN 1 ELSE 0 END DESC,\n        ordered.change_order DESC,\n        ordered.base_producer_id DESC\n    ) AS winner FROM (\n      SELECT contribution.*,\n        MAX(CASE WHEN contribution.origin_kind IN ('run_result','copied_result')\n          THEN contribution.change_order END) OVER cell AS last_generated,\n        MAX(CASE WHEN contribution.origin_kind='source_cell'\n          THEN contribution.change_order END) OVER cell AS last_overwrite,\n        MAX(CASE WHEN contribution.origin_kind IN ('run_result','copied_result')\n          AND contribution.edit_supersession>=1\n          THEN contribution.change_order END) OVER cell AS last_replacement,\n        MAX(CASE WHEN contribution.origin_kind IN ('run_result','copied_result')\n          AND contribution.edit_supersession=2\n          THEN contribution.change_order END) OVER cell AS last_descriptor_replacement\n      FROM cell_contributions contribution\n      WINDOW cell AS (PARTITION BY contribution.column_id,contribution.row_id)\n    ) ordered\n  ) ranked\n  LEFT JOIN cells cell ON ranked.origin_kind='source_cell' AND cell.row_id=ranked.row_id\n    AND cell.column_id=ranked.column_id AND cell.producer_id IS ranked.base_producer_id\n  LEFT JOIN edits edit ON ranked.origin_kind='manual_edit' AND edit.row_id=ranked.row_id\n    AND edit.column_id=ranked.column_id AND edit.op_id=ranked.origin_op_id\n  LEFT JOIN results result ON ranked.origin_kind='run_result' AND result.row_id=ranked.row_id\n    AND result.column_id=ranked.column_id AND result.run_id=ranked.origin_run_id AND result.published=1\n  LEFT JOIN copied_result_values copy ON ranked.origin_kind='copied_result' AND copy.op_id=ranked.origin_op_id\n    AND copy.row_id=ranked.row_id AND copy.column_id=ranked.column_id\n  WHERE ranked.winner=1\n) payload\nJOIN columns descriptor ON descriptor.id=payload.column_id\nJOIN rows row ON row.id=payload.row_id AND row.sheet_id=descriptor.sheet_id\nLEFT JOIN cell_authority_revisions revision ON revision.column_id=payload.column_id\n;\nCREATE VIEW IF NOT EXISTS dirty_cell_heads AS\n\nSELECT payload.column_id,payload.row_id,\n       COALESCE(revision.revision,1) AS retrieval_revision,\n       payload.origin_kind,payload.origin_op_id,payload.origin_run_id,payload.base_producer_id,\n       CASE\n         WHEN payload.value_kind IS NULL OR payload.value_kind='null' THEN 'missing'\n         WHEN descriptor.type IN ('text','category','timestamped_transcript')\n           AND payload.value_kind='text' THEN 'valid'\n         WHEN descriptor.type='json' AND payload.value_kind='json' THEN 'valid'\n         WHEN descriptor.type IN ('number','integer','boolean') AND payload.value_kind IN ('text','json')\n           THEN 'invalid'\n         ELSE frisket_cell_validity(descriptor.type,payload.value_kind,payload.value)\n       END AS validity,\n       CASE WHEN payload.value_kind IN ('null','integer','real','boolean')\n         OR (payload.value_kind IN ('text','bigint') AND length(CAST(payload.value AS BLOB))<=512)\n         THEN payload.value_kind END AS inline_value_kind,\n       CASE WHEN payload.value_kind IN ('null','integer','real','boolean')\n         OR (payload.value_kind IN ('text','bigint') AND length(CAST(payload.value AS BLOB))<=512)\n         THEN payload.value END AS inline_value,\n       payload.outcome\nFROM (\n  SELECT ranked.*,\n       CASE ranked.origin_kind\n         WHEN 'source_cell' THEN cell.value_kind\n         WHEN 'copied_result' THEN CASE WHEN copy.outcome='completed' THEN copy.value_kind END\n         WHEN 'manual_edit' THEN edit.value_kind\n         WHEN 'run_result' THEN CASE result.publication_effect\n           WHEN 'publish_value' THEN result.value_kind WHEN 'publish_null' THEN 'null' END END AS value_kind,\n       CASE ranked.origin_kind\n         WHEN 'source_cell' THEN cell.value WHEN 'manual_edit' THEN edit.value\n         WHEN 'copied_result' THEN CASE WHEN copy.outcome='completed' THEN copy.value END\n         WHEN 'run_result' THEN CASE WHEN result.publication_effect='publish_value' THEN result.value END END AS value,\n       CASE WHEN ranked.origin_kind='copied_result' THEN copy.outcome\n            WHEN ranked.origin_kind!='run_result' THEN 'completed'\n            WHEN result.publication_effect IN ('publish_value','publish_null') THEN 'completed'\n            WHEN result.outcome='not_completed' THEN 'not_completed'\n            WHEN result.row_id IS NOT NULL THEN 'failed'\n            WHEN ranked.publication_closed=0 THEN 'pending' ELSE 'not_completed' END AS outcome\n  FROM (\n    SELECT ordered.*,ROW_NUMBER() OVER (\n      PARTITION BY ordered.column_id,ordered.row_id\n      ORDER BY CASE WHEN ordered.origin_kind='manual_edit'\n            AND COALESCE(ordered.last_overwrite,-1)<ordered.change_order\n            AND COALESCE(ordered.last_descriptor_replacement,-1)<ordered.change_order\n            AND (ordered.edit_supersession=2\n              OR COALESCE(ordered.last_replacement,-1)<ordered.change_order)\n          THEN MAX(ordered.change_order,COALESCE(ordered.last_generated,-1))\n          ELSE ordered.change_order END DESC,\n        CASE ordered.origin_kind WHEN 'manual_edit' THEN 2 WHEN 'run_result' THEN 1 ELSE 0 END DESC,\n        ordered.change_order DESC,\n        ordered.base_producer_id DESC\n    ) AS winner FROM (\n      SELECT contribution.*,\n        MAX(CASE WHEN contribution.origin_kind IN ('run_result','copied_result')\n          THEN contribution.change_order END) OVER cell AS last_generated,\n        MAX(CASE WHEN contribution.origin_kind='source_cell'\n          THEN contribution.change_order END) OVER cell AS last_overwrite,\n        MAX(CASE WHEN contribution.origin_kind IN ('run_result','copied_result')\n          AND contribution.edit_supersession>=1\n          THEN contribution.change_order END) OVER cell AS last_replacement,\n        MAX(CASE WHEN contribution.origin_kind IN ('run_result','copied_result')\n          AND contribution.edit_supersession=2\n          THEN contribution.change_order END) OVER cell AS last_descriptor_replacement\n      FROM current_cell_repair dirty CROSS JOIN cell_contributions contribution ON contribution.column_id=dirty.column_id AND contribution.row_id BETWEEN dirty.row_id_start AND dirty.row_id_end\n      WINDOW cell AS (PARTITION BY contribution.column_id,contribution.row_id)\n    ) ordered\n  ) ranked\n  LEFT JOIN cells cell ON ranked.origin_kind='source_cell' AND cell.row_id=ranked.row_id\n    AND cell.column_id=ranked.column_id AND cell.producer_id IS ranked.base_producer_id\n  LEFT JOIN edits edit ON ranked.origin_kind='manual_edit' AND edit.row_id=ranked.row_id\n    AND edit.column_id=ranked.column_id AND edit.op_id=ranked.origin_op_id\n  LEFT JOIN results result ON ranked.origin_kind='run_result' AND result.row_id=ranked.row_id\n    AND result.column_id=ranked.column_id AND result.run_id=ranked.origin_run_id AND result.published=1\n  LEFT JOIN copied_result_values copy ON ranked.origin_kind='copied_result' AND copy.op_id=ranked.origin_op_id\n    AND copy.row_id=ranked.row_id AND copy.column_id=ranked.column_id\n  WHERE ranked.winner=1\n) payload\nJOIN columns descriptor ON descriptor.id=payload.column_id\nJOIN rows row ON row.id=payload.row_id AND row.sheet_id=descriptor.sheet_id\nLEFT JOIN cell_authority_revisions revision ON revision.column_id=payload.column_id\n;\nCREATE VIEW IF NOT EXISTS generated_result_candidates AS\nSELECT * FROM (SELECT column_id,row_id,origin_run_id AS run_id,origin_op_id AS op_id,outcome FROM (\nSELECT payload.column_id,payload.row_id,\n       COALESCE(revision.revision,1) AS retrieval_revision,\n       payload.origin_kind,payload.origin_op_id,payload.origin_run_id,payload.base_producer_id,\n       CASE\n         WHEN payload.value_kind IS NULL OR payload.value_kind='null' THEN 'missing'\n         WHEN descriptor.type IN ('text','category','timestamped_transcript')\n           AND payload.value_kind='text' THEN 'valid'\n         WHEN descriptor.type='json' AND payload.value_kind='json' THEN 'valid'\n         WHEN descriptor.type IN ('number','integer','boolean') AND payload.value_kind IN ('text','json')\n           THEN 'invalid'\n         ELSE frisket_cell_validity(descriptor.type,payload.value_kind,payload.value)\n       END AS validity,\n       CASE WHEN payload.value_kind IN ('null','integer','real','boolean')\n         OR (payload.value_kind IN ('text','bigint') AND length(CAST(payload.value AS BLOB))<=512)\n         THEN payload.value_kind END AS inline_value_kind,\n       CASE WHEN payload.value_kind IN ('null','integer','real','boolean')\n         OR (payload.value_kind IN ('text','bigint') AND length(CAST(payload.value AS BLOB))<=512)\n         THEN payload.value END AS inline_value,\n       payload.outcome\nFROM (\n  SELECT ranked.*,\n       CASE ranked.origin_kind\n         WHEN 'source_cell' THEN cell.value_kind\n         WHEN 'copied_result' THEN CASE WHEN copy.outcome='completed' THEN copy.value_kind END\n         WHEN 'manual_edit' THEN edit.value_kind\n         WHEN 'run_result' THEN CASE result.publication_effect\n           WHEN 'publish_value' THEN result.value_kind WHEN 'publish_null' THEN 'null' END END AS value_kind,\n       CASE ranked.origin_kind\n         WHEN 'source_cell' THEN cell.value WHEN 'manual_edit' THEN edit.value\n         WHEN 'copied_result' THEN CASE WHEN copy.outcome='completed' THEN copy.value END\n         WHEN 'run_result' THEN CASE WHEN result.publication_effect='publish_value' THEN result.value END END AS value,\n       CASE WHEN ranked.origin_kind='copied_result' THEN copy.outcome\n            WHEN ranked.origin_kind!='run_result' THEN 'completed'\n            WHEN result.publication_effect IN ('publish_value','publish_null') THEN 'completed'\n            WHEN result.outcome='not_completed' THEN 'not_completed'\n            WHEN result.row_id IS NOT NULL THEN 'failed'\n            WHEN ranked.publication_closed=0 THEN 'pending' ELSE 'not_completed' END AS outcome\n  FROM (\n    SELECT ordered.*,ROW_NUMBER() OVER (\n      PARTITION BY ordered.column_id,ordered.row_id\n      ORDER BY CASE WHEN ordered.origin_kind='manual_edit'\n            AND COALESCE(ordered.last_overwrite,-1)<ordered.change_order\n            AND COALESCE(ordered.last_descriptor_replacement,-1)<ordered.change_order\n            AND (ordered.edit_supersession=2\n              OR COALESCE(ordered.last_replacement,-1)<ordered.change_order)\n          THEN MAX(ordered.change_order,COALESCE(ordered.last_generated,-1))\n          ELSE ordered.change_order END DESC,\n        CASE ordered.origin_kind WHEN 'manual_edit' THEN 2 WHEN 'run_result' THEN 1 ELSE 0 END DESC,\n        ordered.change_order DESC,\n        ordered.base_producer_id DESC\n    ) AS winner FROM (\n      SELECT contribution.*,\n        MAX(CASE WHEN contribution.origin_kind IN ('run_result','copied_result')\n          THEN contribution.change_order END) OVER cell AS last_generated,\n        MAX(CASE WHEN contribution.origin_kind='source_cell'\n          THEN contribution.change_order END) OVER cell AS last_overwrite,\n        MAX(CASE WHEN contribution.origin_kind IN ('run_result','copied_result')\n          AND contribution.edit_supersession>=1\n          THEN contribution.change_order END) OVER cell AS last_replacement,\n        MAX(CASE WHEN contribution.origin_kind IN ('run_result','copied_result')\n          AND contribution.edit_supersession=2\n          THEN contribution.change_order END) OVER cell AS last_descriptor_replacement\n      FROM cell_contributions contribution WHERE contribution.origin_kind!='manual_edit'\n      WINDOW cell AS (PARTITION BY contribution.column_id,contribution.row_id)\n    ) ordered\n  ) ranked\n  LEFT JOIN cells cell ON ranked.origin_kind='source_cell' AND cell.row_id=ranked.row_id\n    AND cell.column_id=ranked.column_id AND cell.producer_id IS ranked.base_producer_id\n  LEFT JOIN edits edit ON ranked.origin_kind='manual_edit' AND edit.row_id=ranked.row_id\n    AND edit.column_id=ranked.column_id AND edit.op_id=ranked.origin_op_id\n  LEFT JOIN results result ON ranked.origin_kind='run_result' AND result.row_id=ranked.row_id\n    AND result.column_id=ranked.column_id AND result.run_id=ranked.origin_run_id AND result.published=1\n  LEFT JOIN copied_result_values copy ON ranked.origin_kind='copied_result' AND copy.op_id=ranked.origin_op_id\n    AND copy.row_id=ranked.row_id AND copy.column_id=ranked.column_id\n  WHERE ranked.winner=1\n) payload\nJOIN columns descriptor ON descriptor.id=payload.column_id\nJOIN rows row ON row.id=payload.row_id AND row.sheet_id=descriptor.sheet_id\nLEFT JOIN cell_authority_revisions revision ON revision.column_id=payload.column_id\n) WHERE origin_kind='run_result') WHERE outcome IN ('completed','failed');\n\nCREATE VIEW IF NOT EXISTS effective_current_cells AS\nSELECT head.* FROM current_cells head WHERE NOT EXISTS (\n  SELECT 1 FROM current_cell_repair dirty WHERE dirty.column_id=head.column_id\n  AND head.row_id BETWEEN dirty.row_id_start AND dirty.row_id_end\n)\nUNION ALL\nSELECT head.* FROM dirty_cell_heads head WHERE EXISTS (\n  SELECT 1 FROM current_cell_repair dirty WHERE dirty.column_id=head.column_id\n  AND head.row_id BETWEEN dirty.row_id_start AND dirty.row_id_end\n);\n\n-- Publication fences are separate from current values and candidate discovery.\nCREATE VIEW IF NOT EXISTS published_result_bases AS\nSELECT column_id,row_id,run_id FROM (\n  SELECT result.column_id,result.row_id,result.run_id,\n         ROW_NUMBER() OVER (\n           PARTITION BY result.column_id,result.row_id\n           ORDER BY COALESCE(op.change_order,0) DESC,run.id DESC\n         ) AS winner\n  FROM results result JOIN runs run ON run.id=result.run_id\n  JOIN ops op ON op.id=run.op_id\n  WHERE result.published=1 AND result.publication_effect IN ('publish_value','publish_null','publish_error')\n    AND op.status='applied'\n) WHERE winner=1;\n"

PRE_CHANGES_DESCRIPTOR_SCHEMA_SQL = "\nCREATE TABLE IF NOT EXISTS column_descriptor_changes (\n  op_id INTEGER NOT NULL REFERENCES ops(id) ON DELETE CASCADE,\n  column_id INTEGER NOT NULL REFERENCES columns(id) ON DELETE CASCADE,\n  property TEXT NOT NULL CHECK(property IN ('type','format','semantic_type')),\n  PRIMARY KEY(column_id,property,op_id)\n);\nCREATE INDEX IF NOT EXISTS idx_descriptor_change_op ON column_descriptor_changes(op_id);\n"

PRE_CHANGES_STRUCTURAL_SCHEMA_SQL = "\nCREATE TABLE IF NOT EXISTS structural_changes (\n  op_id INTEGER NOT NULL REFERENCES ops(id) ON DELETE CASCADE,\n  kind TEXT NOT NULL CHECK(kind IN ('row','column','sheet')),\n  object_id INTEGER NOT NULL,\n  before_visible INTEGER NOT NULL CHECK(before_visible IN (0,1)),\n  after_visible INTEGER NOT NULL CHECK(after_visible IN (0,1)),\n  PRIMARY KEY(kind,object_id,op_id)\n);\nCREATE INDEX IF NOT EXISTS idx_structural_change_op ON structural_changes(op_id);\n"

PRE_CHANGES_COPIED_RESULTS_SCHEMA_SQL = "\nCREATE TABLE IF NOT EXISTS copied_result_outcomes (\n  op_id INTEGER NOT NULL REFERENCES ops(id) ON DELETE RESTRICT,\n  row_id INTEGER NOT NULL REFERENCES rows(id) ON DELETE CASCADE,\n  column_id INTEGER NOT NULL REFERENCES columns(id) ON DELETE CASCADE,\n  source_run_id INTEGER,\n  source_row_id INTEGER,\n  source_column_id INTEGER,\n  review_state TEXT NOT NULL DEFAULT 'unreviewed',\n  review_decision TEXT CHECK(review_decision IN ('accept','reject','reject_clear','edit')),\n  review_note TEXT,\n  PRIMARY KEY(op_id,row_id,column_id),\n  FOREIGN KEY(source_run_id,source_row_id,source_column_id)\n    REFERENCES results(run_id,row_id,column_id) ON DELETE RESTRICT,\n  CHECK ((source_run_id IS NULL AND source_row_id IS NULL AND source_column_id IS NULL)\n    OR (source_run_id IS NOT NULL AND source_row_id IS NOT NULL AND source_column_id IS NOT NULL))\n) WITHOUT ROWID;\nCREATE INDEX IF NOT EXISTS idx_copied_results_source\n  ON copied_result_outcomes(source_run_id,source_row_id,source_column_id);\nCREATE VIEW IF NOT EXISTS copied_result_values AS\nSELECT copy.*,result.value_kind,result.value,result.publication_effect,\n       result.outcome AS result_outcome,result.error,result.error_code,\n       result.confidence,result.justification,result.warnings,\n       CASE WHEN copy.source_run_id IS NULL THEN 'not_completed'\n            WHEN result.outcome='not_completed' THEN 'not_completed'\n            WHEN result.publication_effect IN ('publish_value','publish_null') THEN 'completed'\n            WHEN result.publication_effect='retain' AND result.error IS NULL\n              AND result.outcome IN ('ok','empty','unverified_memory') THEN 'completed'\n            ELSE 'failed' END AS outcome\nFROM copied_result_outcomes copy LEFT JOIN results result\n  ON result.run_id=copy.source_run_id AND result.row_id=copy.source_row_id\n AND result.column_id=copy.source_column_id;\n"

PRE_CHANGES_CONSUMED_SOURCE_SCHEMA_SQL = "\nCREATE TABLE IF NOT EXISTS consumed_source_bundles (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  capture_key TEXT NOT NULL UNIQUE,\n  owner_op_id INTEGER NOT NULL REFERENCES ops(id) ON DELETE CASCADE,\n  run_id INTEGER REFERENCES runs(id) ON DELETE CASCADE,\n  row_id INTEGER REFERENCES rows(id) ON DELETE CASCADE,\n  output_sheet_id INTEGER NOT NULL REFERENCES sheets(id) ON DELETE CASCADE,\n  kind TEXT NOT NULL CHECK(kind IN ('row','aggregate')),\n  input_fingerprint TEXT NOT NULL,\n  capture_json TEXT NOT NULL CHECK(json_valid(capture_json)),\n  state TEXT NOT NULL CHECK(state IN ('fresh','stale','unknown','checking')),\n  checked_revisions_json TEXT NOT NULL CHECK(json_valid(checked_revisions_json))\n);\nCREATE INDEX IF NOT EXISTS idx_consumed_sources_sheet\n  ON consumed_source_bundles(output_sheet_id,owner_op_id);\nCREATE INDEX IF NOT EXISTS idx_consumed_sources_run_row\n  ON consumed_source_bundles(run_id,row_id);\nCREATE INDEX IF NOT EXISTS idx_consumed_sources_fingerprint\n  ON consumed_source_bundles(input_fingerprint);\nCREATE INDEX IF NOT EXISTS idx_consumed_sources_kind\n  ON consumed_source_bundles(kind,id);\nCREATE INDEX IF NOT EXISTS idx_consumed_sources_input_row\n  ON consumed_source_bundles(json_extract(capture_json,'$.row_id')) WHERE kind='row';\nCREATE TABLE IF NOT EXISTS consumed_source_columns (\n  bundle_id INTEGER NOT NULL REFERENCES consumed_source_bundles(id) ON DELETE CASCADE,\n  column_id INTEGER NOT NULL REFERENCES columns(id) ON DELETE CASCADE,\n  PRIMARY KEY(bundle_id,column_id)\n) WITHOUT ROWID;\nCREATE INDEX IF NOT EXISTS idx_consumed_sources_column\n  ON consumed_source_columns(column_id,bundle_id);\n\nCREATE TRIGGER IF NOT EXISTS positioned_guard_source_artifacts_insert\nAFTER INSERT ON source_artifacts WHEN (json_type(NEW.metadata,'$.engine') IS NOT NULL AND json_type(NEW.metadata,'$.page_images')='object')\nBEGIN\n  INSERT INTO meta(key,value) VALUES ('positioned_source_revision','1')\n  ON CONFLICT(key) DO UPDATE SET value=CAST(meta.value AS INTEGER)+1;\nEND;\n\nCREATE TRIGGER IF NOT EXISTS positioned_guard_source_artifacts_update\nAFTER UPDATE ON source_artifacts WHEN (json_type(OLD.metadata,'$.engine') IS NOT NULL AND json_type(OLD.metadata,'$.page_images')='object') OR (json_type(NEW.metadata,'$.engine') IS NOT NULL AND json_type(NEW.metadata,'$.page_images')='object')\nBEGIN\n  INSERT INTO meta(key,value) VALUES ('positioned_source_revision','1')\n  ON CONFLICT(key) DO UPDATE SET value=CAST(meta.value AS INTEGER)+1;\nEND;\n\nCREATE TRIGGER IF NOT EXISTS positioned_guard_source_artifacts_delete\nAFTER DELETE ON source_artifacts WHEN (json_type(OLD.metadata,'$.engine') IS NOT NULL AND json_type(OLD.metadata,'$.page_images')='object')\nBEGIN\n  INSERT INTO meta(key,value) VALUES ('positioned_source_revision','1')\n  ON CONFLICT(key) DO UPDATE SET value=CAST(meta.value AS INTEGER)+1;\nEND;\n\nCREATE TRIGGER IF NOT EXISTS positioned_guard_source_spans_insert\nAFTER INSERT ON source_spans WHEN EXISTS(SELECT 1 FROM source_artifacts artifact WHERE artifact.id=NEW.artifact_id AND json_type(artifact.metadata,'$.engine') IS NOT NULL AND json_type(artifact.metadata,'$.page_images')='object')\nBEGIN\n  INSERT INTO meta(key,value) VALUES ('positioned_source_revision','1')\n  ON CONFLICT(key) DO UPDATE SET value=CAST(meta.value AS INTEGER)+1;\nEND;\n\nCREATE TRIGGER IF NOT EXISTS positioned_guard_source_spans_update\nAFTER UPDATE ON source_spans WHEN EXISTS(SELECT 1 FROM source_artifacts artifact WHERE artifact.id=OLD.artifact_id AND json_type(artifact.metadata,'$.engine') IS NOT NULL AND json_type(artifact.metadata,'$.page_images')='object') OR EXISTS(SELECT 1 FROM source_artifacts artifact WHERE artifact.id=NEW.artifact_id AND json_type(artifact.metadata,'$.engine') IS NOT NULL AND json_type(artifact.metadata,'$.page_images')='object')\nBEGIN\n  INSERT INTO meta(key,value) VALUES ('positioned_source_revision','1')\n  ON CONFLICT(key) DO UPDATE SET value=CAST(meta.value AS INTEGER)+1;\nEND;\n\nCREATE TRIGGER IF NOT EXISTS positioned_guard_source_spans_delete\nAFTER DELETE ON source_spans WHEN EXISTS(SELECT 1 FROM source_artifacts artifact WHERE artifact.id=OLD.artifact_id AND json_type(artifact.metadata,'$.engine') IS NOT NULL AND json_type(artifact.metadata,'$.page_images')='object')\nBEGIN\n  INSERT INTO meta(key,value) VALUES ('positioned_source_revision','1')\n  ON CONFLICT(key) DO UPDATE SET value=CAST(meta.value AS INTEGER)+1;\nEND;\n"

PRE_CHANGES_JUDGMENT_SCHEMA_SQL = "\nCREATE TABLE IF NOT EXISTS result_judgment_changes (\n op_id INTEGER NOT NULL REFERENCES ops(id) ON DELETE CASCADE,\n target TEXT NOT NULL,\n property TEXT NOT NULL CHECK(property IN ('state','decision','note')),\n PRIMARY KEY(target,property,op_id)\n);\nCREATE INDEX IF NOT EXISTS idx_judgment_change_op ON result_judgment_changes(op_id);\n"

PRE_CHANGES_CURRENT_CELL_VALUES_SQL = "CREATE VIEW IF NOT EXISTS current_cell_values AS\n\nSELECT head.column_id,head.row_id,\n       CASE WHEN head.inline_value_kind IS NOT NULL\n       THEN head.inline_value_kind ELSE CASE head.origin_kind\n         WHEN 'source_cell' THEN (\n           SELECT CASE source.value_kind\n             WHEN 'prepared_content_ref' THEN 'text' ELSE source.value_kind END\n           FROM cells AS source\n           WHERE source.row_id=head.row_id\n             AND source.column_id=head.column_id\n             AND source.producer_id IS head.base_producer_id\n         )\n         WHEN 'run_result' THEN (\n           SELECT CASE result.publication_effect\n             WHEN 'publish_value' THEN CASE result.value_kind\n               WHEN 'prepared_content_ref' THEN 'text' ELSE result.value_kind END\n             WHEN 'publish_null' THEN 'null'\n           END\n           FROM results AS result\n           WHERE result.run_id=head.origin_run_id\n             AND result.row_id=head.row_id\n             AND result.column_id=head.column_id AND result.published=1\n         )\n         WHEN 'copied_result' THEN (\n           SELECT CASE result.publication_effect WHEN 'publish_value' THEN CASE result.value_kind WHEN 'prepared_content_ref' THEN 'text' ELSE result.value_kind END WHEN 'publish_null' THEN 'null' END\n           FROM copied_result_values result WHERE result.op_id=head.origin_op_id\n             AND result.row_id=head.row_id AND result.column_id=head.column_id\n         )\n         WHEN 'manual_edit' THEN (\n           SELECT CASE edit.value_kind\n             WHEN 'prepared_content_ref' THEN 'text' ELSE edit.value_kind END\n           FROM edits AS edit\n           WHERE edit.op_id=head.origin_op_id\n             AND edit.row_id=head.row_id\n             AND edit.column_id=head.column_id\n         )\n       END END AS value_kind,\n       CASE WHEN head.inline_value_kind IS NOT NULL\n       THEN head.inline_value ELSE CASE head.origin_kind\n         WHEN 'source_cell' THEN (\n           SELECT CASE source.value_kind WHEN 'prepared_content_ref' THEN (\n             SELECT prepared.value FROM prepared_content_ref_values AS prepared\n             WHERE prepared.ref_id=source.value\n           ) ELSE source.value END FROM cells AS source\n           WHERE source.row_id=head.row_id\n             AND source.column_id=head.column_id\n             AND source.producer_id IS head.base_producer_id\n         )\n         WHEN 'run_result' THEN (\n           SELECT CASE WHEN result.publication_effect='publish_value'\n             THEN CASE result.value_kind WHEN 'prepared_content_ref' THEN (\n               SELECT prepared.value FROM prepared_content_ref_values AS prepared\n               WHERE prepared.ref_id=result.value\n             ) ELSE result.value END END\n           FROM results AS result\n           WHERE result.run_id=head.origin_run_id\n             AND result.row_id=head.row_id\n             AND result.column_id=head.column_id AND result.published=1\n         )\n         WHEN 'copied_result' THEN (\n           SELECT CASE WHEN result.publication_effect='publish_value' THEN CASE result.value_kind WHEN 'prepared_content_ref' THEN (SELECT prepared.value FROM prepared_content_ref_values prepared WHERE prepared.ref_id=result.value) ELSE result.value END END\n           FROM copied_result_values result WHERE result.op_id=head.origin_op_id\n             AND result.row_id=head.row_id AND result.column_id=head.column_id\n         )\n         WHEN 'manual_edit' THEN (\n           SELECT CASE edit.value_kind WHEN 'prepared_content_ref' THEN (\n             SELECT prepared.value FROM prepared_content_ref_values AS prepared\n             WHERE prepared.ref_id=edit.value\n           ) ELSE edit.value END FROM edits AS edit\n           WHERE edit.op_id=head.origin_op_id\n             AND edit.row_id=head.row_id\n             AND edit.column_id=head.column_id\n         )\n       END END AS value,\n       head.origin_kind,head.origin_op_id,head.origin_run_id,\n       head.base_producer_id,head.validity,head.outcome,\n       CASE WHEN head.inline_value_kind IS NULL THEN CASE head.origin_kind\n         WHEN 'source_cell' THEN (\n           SELECT CASE source.value_kind WHEN 'prepared_content_ref'\n             THEN source.value END FROM cells AS source\n           WHERE source.row_id=head.row_id\n             AND source.column_id=head.column_id\n             AND source.producer_id IS head.base_producer_id\n         )\n         WHEN 'run_result' THEN (\n           SELECT CASE WHEN result.publication_effect='publish_value'\n             AND result.value_kind='prepared_content_ref' THEN result.value END\n           FROM results AS result\n           WHERE result.run_id=head.origin_run_id\n             AND result.row_id=head.row_id\n             AND result.column_id=head.column_id AND result.published=1\n         )\n         WHEN 'copied_result' THEN (\n           SELECT CASE WHEN result.publication_effect='publish_value' AND result.value_kind='prepared_content_ref' THEN result.value END\n           FROM copied_result_values result WHERE result.op_id=head.origin_op_id\n             AND result.row_id=head.row_id AND result.column_id=head.column_id\n         )\n         WHEN 'manual_edit' THEN (\n           SELECT CASE edit.value_kind WHEN 'prepared_content_ref'\n             THEN edit.value END FROM edits AS edit\n           WHERE edit.op_id=head.origin_op_id\n             AND edit.row_id=head.row_id\n             AND edit.column_id=head.column_id\n         )\n       END END AS prepared_ref_id\nFROM effective_current_cells AS head\n;"

PRE_CHANGES_MATERIALIZED_LINEAGE_SCHEMA_SQL = "\n-- MATERIALIZED_ROW_SOURCES_BEGIN\nCREATE TABLE IF NOT EXISTS materialized_row_sources (\n  materialized_row_id INTEGER NOT NULL REFERENCES rows(id) ON DELETE CASCADE,\n  source_row_id INTEGER NOT NULL REFERENCES rows(id) ON DELETE CASCADE,\n  source_sheet_id INTEGER NOT NULL REFERENCES sheets(id) ON DELETE CASCADE,\n  op_id INTEGER NOT NULL REFERENCES ops(id) ON DELETE CASCADE,\n  role TEXT NOT NULL CHECK (\n    role IN (\n      'edge_source', 'edge_target', 'aggregate_source', 'join_left', 'join_right'\n    )\n  ),\n  PRIMARY KEY (materialized_row_id, source_row_id, role, op_id)\n);\nCREATE INDEX IF NOT EXISTS idx_materialized_row_sources_source\n  ON materialized_row_sources(source_sheet_id, source_row_id, role);\nCREATE INDEX IF NOT EXISTS idx_materialized_row_sources_materialized\n  ON materialized_row_sources(materialized_row_id, role);\nCREATE INDEX IF NOT EXISTS idx_materialized_row_sources_op\n  ON materialized_row_sources(op_id);\n-- MATERIALIZED_ROW_SOURCES_END\nCREATE VIEW IF NOT EXISTS current_materialized_row_sources AS\nSELECT m.materialized_row_id,m.source_row_id,m.source_sheet_id,m.op_id,m.role\nFROM materialized_row_sources m\nWHERE m.op_id = (\n  SELECT candidate.op_id FROM materialized_row_sources candidate\n  JOIN ops owner ON owner.id=candidate.op_id\n  WHERE candidate.materialized_row_id=m.materialized_row_id AND owner.status='applied'\n  ORDER BY COALESCE(owner.change_order,0) DESC,owner.id DESC LIMIT 1\n);\n"

PRE_CHANGES_DOCUMENT_TEXT_SCHEMA_SQL = "\nCREATE TABLE IF NOT EXISTS document_text_column_roles (\n  source_column_id INTEGER PRIMARY KEY\n    REFERENCES columns(id) ON DELETE CASCADE,\n  text_column_id INTEGER NOT NULL UNIQUE\n    REFERENCES columns(id) ON DELETE CASCADE,\n  CHECK (source_column_id <> text_column_id)\n) WITHOUT ROWID;\n\nCREATE TABLE IF NOT EXISTS document_text_manual_pins (\n  edit_op_id INTEGER NOT NULL,\n  row_id INTEGER NOT NULL,\n  text_column_id INTEGER NOT NULL,\n  prepared_ref_id INTEGER NOT NULL\n    REFERENCES prepared_content_refs(id) ON DELETE RESTRICT,\n  PRIMARY KEY (edit_op_id,row_id,text_column_id),\n  FOREIGN KEY (edit_op_id,row_id,text_column_id)\n    REFERENCES edits(op_id,row_id,column_id) ON DELETE CASCADE\n) WITHOUT ROWID;\n"

PRE_CHANGES_DOCUMENT_TEXT_SELECTION_VIEW_SQL = "\nCREATE VIEW IF NOT EXISTS current_document_text_selections AS\nSELECT source_column.sheet_id AS source_sheet_id,\n       source_head.row_id AS row_id,\n       role.source_column_id AS source_column_id,\n       role.text_column_id AS text_column_id,\n       source_head.retrieval_revision AS source_retrieval_revision,\n       text_head.retrieval_revision AS text_retrieval_revision,\n       json_extract(source_live.value,'$.blob') AS source_blob_hash,\n       CASE WHEN json_type(source_live.value,'$.page')='integer'\n            THEN CAST(json_extract(source_live.value,'$.page') AS INTEGER) END\n         AS source_page_number,\n       text_live.prepared_ref_id AS prepared_ref_id,\n       COALESCE(text_live.prepared_ref_id,pin.prepared_ref_id)\n         AS provenance_ref_id,\n       ref.set_id AS set_id,\n       content.source_artifact_id AS source_artifact_id,\n       ref.page_number AS ref_page_number,\n       artifact.page_count AS page_count,\n       source_column.hidden AS source_hidden,\n       text_column.hidden AS text_hidden\nFROM document_text_column_roles role\nJOIN columns source_column ON source_column.id=role.source_column_id\nJOIN columns text_column ON text_column.id=role.text_column_id\nJOIN effective_current_cells source_head ON source_head.column_id=role.source_column_id\nJOIN current_cell_values source_live\n  ON source_live.column_id=source_head.column_id\n AND source_live.row_id=source_head.row_id\nJOIN effective_current_cells text_head\n  ON text_head.column_id=role.text_column_id\n AND text_head.row_id=source_head.row_id\nJOIN current_cell_values text_live\n  ON text_live.column_id=text_head.column_id\n AND text_live.row_id=text_head.row_id\nLEFT JOIN document_text_manual_pins pin\n  ON text_head.origin_kind='manual_edit'\n AND pin.edit_op_id=text_head.origin_op_id\n AND pin.row_id=text_head.row_id\n AND pin.text_column_id=text_head.column_id\nJOIN prepared_content_refs ref\n  ON ref.id=COALESCE(text_live.prepared_ref_id,pin.prepared_ref_id)\nJOIN prepared_content_sets content ON content.id=ref.set_id\nJOIN source_artifacts artifact ON artifact.id=content.source_artifact_id\nWHERE source_column.sheet_id=text_column.sheet_id\n  AND source_column.type IN ('file','image')\n  AND text_column.type='text'\n  AND source_column.active=1\n  AND text_column.active=1\n  AND source_live.validity='valid'\n  AND source_live.value_kind='json'\n  AND text_live.validity='valid'\n  AND text_live.value_kind='text'\n  AND typeof(json_extract(source_live.value,'$.blob'))='text'\n  AND length(json_extract(source_live.value,'$.blob'))>0\n  AND (\n    json_type(source_live.value,'$.page') IS NULL\n    OR json_type(source_live.value,'$.page')='null'\n    OR (\n      source_column.type='file'\n      AND json_type(source_live.value,'$.page')='integer'\n      AND json_extract(source_live.value,'$.page')>0\n    )\n)\n  AND artifact.blob_hash=json_extract(source_live.value,'$.blob')\n  AND ref.page_number IS CASE\n    WHEN json_type(source_live.value,'$.page')='integer'\n      THEN CAST(json_extract(source_live.value,'$.page') AS INTEGER)\n    ELSE NULL END\n  AND (\n    (\n      artifact.source_sheet_id=source_column.sheet_id\n      AND artifact.source_row_id=source_head.row_id\n      AND artifact.source_column_id=role.source_column_id\n    )\n    OR (\n      ref.page_number IS NOT NULL\n      AND EXISTS (\n        SELECT 1\n        FROM source_spans source_span\n        JOIN citation_spans linked ON linked.span_id=source_span.id\n        JOIN citations source_link ON source_link.id=linked.citation_id\n        WHERE source_span.artifact_id=artifact.id\n          AND source_span.span_kind='page'\n          AND source_span.page_start=ref.page_number\n          AND source_span.page_end=ref.page_number\n          AND source_link.status='active'\n          AND (source_link.op_id IS NULL OR EXISTS (SELECT 1 FROM ops citation_owner\n            WHERE citation_owner.id=source_link.op_id AND citation_owner.status='applied'))\n          AND source_link.link_role='primary_support'\n          AND source_link.subject_kind='cell_value'\n          AND source_link.sheet_id=source_column.sheet_id\n          AND source_link.row_id=source_head.row_id\n          AND source_link.column_id=role.source_column_id\n      )\n    )\n  );\n"

